@Composable fun VehiclesScreen(vm:AppViewModel){val dao=vm.repo.db.civicDao();val vehicles by dao.observeVehicles().collectAsState(initial=emptyList());val people by dao.observePeople().collectAsState(initial=emptyList());val messages by dao.observeMessages().collectAsState(initial=emptyList());val services by dao.observeOilServices().collectAsState(initial=emptyList());val settings by vm.settings.collectAsState();val scope=rememberCoroutineScope();var entry by remember{mutableStateOf<Int?>(null)};var chooser by remember{mutableStateOf(false)};var filter by remember{mutableStateOf<Int?>(null)};var selectedVehicleId by remember{mutableStateOf<Long?>(null)}
 BackHandler(enabled=entry!=null||selectedVehicleId!=null){if(entry!=null)entry=null else selectedVehicleId=null}
 if(entry!=null){VehicleEntryPage(vm,entry!!,{entry=null},{entry=null});return}
 selectedVehicleId?.let{id->vehicles.firstOrNull{it.id==id}?.let{vehicle->VehiclePlateDetail(vehicle,people,services,messages,settings.moneyUnit,dao,{selectedVehicleId=null});return}}
 fun allFines(v:VehicleEntity):List<CivicMessageEntity> = messages.filter { message ->
  message.kind==CivicMessageKind.TRAFFIC_FINE &&
   (message.vehicleId==v.id || (message.vehicleId==null && ir.kharjyar.app.core.sms.IranianPlateMatcher.matches(message.body,v.plate)))
 }
 fun unreadFines(v:VehicleEntity):List<CivicMessageEntity> = allFines(v).filter{!it.read}
 val shown=vehicles.filter{filter==null||(filter==1&&unreadFines(it).isNotEmpty())||(filter==0&&unreadFines(it).isEmpty())};Box(Modifier.fillMaxSize()){Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(start=16.dp,end=16.dp,top=12.dp,bottom=92.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){Text("وسایل نقلیه",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(8.dp)){VehicleSummary("بدون جریمه جدید",vehicles.count{unreadFines(it).isEmpty()},Color(0xFF1B8F52),Modifier.weight(1f));VehicleSummary("دارای جریمه جدید",vehicles.count{unreadFines(it).isNotEmpty()},Color(0xFFD33B45),Modifier.weight(1f))};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(filter==null,{filter=null},{Text("همه")});FilterChip(filter==0,{filter=0},{Text("عادی")});FilterChip(filter==1,{filter=1},{Text("جریمه جدید")})};if(shown.isEmpty())Card(Modifier.fillMaxWidth()){Text(if(vehicles.isEmpty())"برای شروع، وسیله نقلیه خود را ثبت کنید." else "وسیله نقلیه‌ای در این فیلتر نیست.",Modifier.padding(24.dp))};shown.forEach{vehicle->val fines=unreadFines(vehicle);val totalFineRial=allFines(vehicle).mapNotNull{ir.kharjyar.app.core.sms.TrafficFineParser.amountRial(it.body)}.sum();val accent=if(fines.isEmpty())Color(0xFF20A565) else Color(0xFFE14B55);val ownerName=vehicle.ownerId?.let{id->people.firstOrNull{it.id==id}?.name}?:"خودم";val vehicleServices=services.filter{it.vehicleId==vehicle.id};val latest=vehicleServices.maxByOrNull{it.servicedAt};Card(colors=CardDefaults.cardColors(containerColor=accent.copy(alpha=.10f)),shape=RoundedCornerShape(16.dp),modifier=Modifier.fillMaxWidth().clickable{selectedVehicleId=vehicle.id}.border(1.3.dp,accent,RoundedCornerShape(16.dp))){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(vehicle.title,style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Text(if(fines.isEmpty())"وضعیت عادی" else "${Digits.toPersian(fines.size.toString())} جریمه جدید",color=accent,fontWeight=FontWeight.Bold)};Text("پلاک ${vehicle.plate} • مالک: $ownerName");if(totalFineRial>0)Text("جمع مبلغ جریمه‌های این پلاک: ${Money.format(totalFineRial,settings.moneyUnit)}",color=Color(0xFFE14B55),fontWeight=FontWeight.Bold);if(latest!=null){HorizontalDivider();Text("آخرین سرویس: کیلومتر ${Digits.toPersian(latest.currentKm.toString())}");Text("تعویض بعدی: ${Digits.toPersian(latest.nextKm.toString())} کیلومتر یا ${PersianDate.fromMillis(latest.nextDueAt).format()}",color=accent);if(latest.oilType.isNotBlank())Text("روغن: ${latest.oilType}")}else Text("هنوز سرویس تعویض روغن ثبت نشده است.",style=MaterialTheme.typography.bodySmall);fines.take(2).forEach{fine->HorizontalDivider();Text(PersianDate.formatDateTime(fine.receivedAt),style=MaterialTheme.typography.labelSmall);Text(fine.body,maxLines=3);TextButton({scope.launch{dao.updateMessage(fine.copy(read=true,vehicleId=vehicle.id))}}){Text("خواندم")}}}}}
 }
 FloatingActionButton({chooser=true},Modifier.align(Alignment.BottomEnd).padding(20.dp)){Icon(Icons.Filled.Add,"افزودن")}
 if(chooser)AlertDialog(onDismissRequest={chooser=false},title={Text("چه موردی ثبت شود؟")},text={Column(verticalArrangement=Arrangement.spacedBy(10.dp)){Button({chooser=false;entry=VEHICLE_ENTRY},Modifier.fillMaxWidth(),border=BorderStroke(1.5.dp,Color(0xFF1B8F52))){Text("وسیله نقلیه جدید")};Button({chooser=false;entry=SERVICE_ENTRY},Modifier.fillMaxWidth(),enabled=vehicles.isNotEmpty(),border=BorderStroke(1.5.dp,Color(0xFFD33B45))){Text("سرویس و تعویض روغن")};if(vehicles.isEmpty())Text("برای ثبت سرویس، ابتدا یک وسیله نقلیه اضافه کنید.",style=MaterialTheme.typography.bodySmall)}},confirmButton={})
}
}

@Composable private fun VehiclePlateDetail(vehicle:VehicleEntity,people:List<CoveredPersonEntity>,services:List<VehicleOilServiceEntity>,messages:List<CivicMessageEntity>,unit:ir.kharjyar.app.core.money.MoneyUnit,dao:CivicDao,onBack:()->Unit){
 val scope=rememberCoroutineScope();val ownerName=vehicle.ownerId?.let{id->people.firstOrNull{it.id==id}?.name}?:"خودم";val vehicleMessages=messages.filter{it.vehicleId==vehicle.id||(it.vehicleId==null&&ir.kharjyar.app.core.sms.IranianPlateMatcher.matches(it.body,vehicle.plate))};val fines=vehicleMessages.filter{it.kind==CivicMessageKind.TRAFFIC_FINE};val totalFine=fines.mapNotNull{ir.kharjyar.app.core.sms.TrafficFineParser.amountRial(it.body)}.sum();val vehicleServices=services.filter{it.vehicleId==vehicle.id}.sortedByDescending{it.servicedAt}
 Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){TextButton(onBack){Icon(Icons.Filled.ArrowBack,null);Text("بازگشت به فهرست پلاک‌ها")};Text(vehicle.title,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Card(Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(5.dp)){Text("پلاک ${vehicle.plate}",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold);Text("مالک: $ownerName");Text("تعداد جرائم: ${Digits.toPersian(fines.size.toString())}");Text("جمع مبلغ جرائم: ${Money.format(totalFine,unit)}",color=Color(0xFFD33B45),fontWeight=FontWeight.Bold)}};Text("جرائم و پیامک‌های این پلاک",style=MaterialTheme.typography.titleMedium);if(vehicleMessages.isEmpty())Text("هنوز پیامکی برای این پلاک ثبت نشده است.");vehicleMessages.sortedByDescending{it.receivedAt}.forEach{m->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(4.dp)){Text(PersianDate.formatDateTime(m.receivedAt),style=MaterialTheme.typography.labelMedium);Text(m.body);if(!m.read)TextButton({scope.launch{dao.updateMessage(m.copy(read=true,vehicleId=vehicle.id))}}){Text("خواندم")}}}};Text("سوابق سرویس",style=MaterialTheme.typography.titleMedium);if(vehicleServices.isEmpty())Text("هنوز سابقه سرویسی ثبت نشده است.");vehicleServices.forEach{s->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text("تاریخ: ${PersianDate.fromMillis(s.servicedAt).format()}");Text("کیلومتر: ${Digits.toPersian(s.currentKm.toString())}");if(s.oilType.isNotBlank())Text("روغن: ${s.oilType}");if(s.note.isNotBlank())Text(s.note)}}}}
}

@Composable private fun VehicleSummary(label:String,count:Int,color:Color,modifier:Modifier){Card(modifier,colors=CardDefaults.cardColors(containerColor=color.copy(.10f))){Column(Modifier.fillMaxWidth().padding(12.dp),horizontalAlignment=Alignment.CenterHorizontally){Text(Digits.toPersian(count.toString()),style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold,color=color);Text(label,style=MaterialTheme.typography.labelMedium)}}}

@Composable private fun IranianPlateInput(value:String,onValueChange:(String)->Unit){
 val parsed=remember(value){ir.kharjyar.app.core.sms.IranianPlateMatcher.extract(value)}
 var left by remember{mutableStateOf(parsed?.leftTwo.orEmpty())};var letter by remember{mutableStateOf(parsed?.letter.orEmpty())};var serial by remember{mutableStateOf(parsed?.serialThree.orEmpty())};var iran by remember{mutableStateOf(parsed?.iranCode.orEmpty())}
 fun emit(l:String=left,ch:String=letter,s:String=serial,i:String=iran){left=l;letter=ch;serial=s;iran=i;onValueChange("$l$ch${s}ایران$i")}
 Column(verticalArrangement=Arrangement.spacedBy(6.dp)){Text("شماره پلاک ایران",style=MaterialTheme.typography.labelLarge);CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr){Card(shape=RoundedCornerShape(10.dp),modifier=Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=Color(0xFFF4F4F4))){Row(Modifier.fillMaxWidth().padding(6.dp),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(4.dp)){Box(Modifier.width(26.dp).height(58.dp).background(Color(0xFF17458A),RoundedCornerShape(5.dp)),contentAlignment=Alignment.Center){Text("IR",color=Color.White,style=MaterialTheme.typography.labelSmall)};OutlinedTextField(left,{emit(l=Digits.normalize(it).filter(Char::isDigit).take(2))},placeholder={Text("۸۶")},singleLine=true,modifier=Modifier.width(58.dp));OutlinedTextField(letter,{raw->emit(ch=raw.filter{it in 'آ'..'ی'||it=='♿'}.take(1))},placeholder={Text("س")},singleLine=true,modifier=Modifier.width(49.dp));OutlinedTextField(serial,{emit(s=Digits.normalize(it).filter(Char::isDigit).take(3))},placeholder={Text("۶۷۳")},singleLine=true,modifier=Modifier.width(76.dp));Column(Modifier.width(72.dp),horizontalAlignment=Alignment.CenterHorizontally){Text("ایران",color=Color.Black,fontWeight=FontWeight.Bold);OutlinedTextField(iran,{emit(i=Digits.normalize(it).filter(Char::isDigit).take(2))},placeholder={Text("۷۳")},singleLine=true,modifier=Modifier.fillMaxWidth())}}}}};Row(verticalAlignment=Alignment.CenterVertically){Text("برای پلاک ویژه: ",style=MaterialTheme.typography.bodySmall);TextButton({emit(ch="♿")}){Text("نماد معلولین ♿")};if(letter=="♿")TextButton({emit(ch="")}){Text("حرف معمولی")}}}
}

@Composable private fun VehicleEntryPage(vm:AppViewModel,kind:Int,onDone:()->Unit,onCancel:()->Unit){val dao=vm.repo.db.civicDao();val vehicles by dao.observeVehicles().collectAsState(initial=emptyList());val people by dao.observePeople().collectAsState(initial=emptyList());val context=LocalContext.current;val scope=rememberCoroutineScope();var title by remember{mutableStateOf("")};var plate by remember{mutableStateOf("")};var owner by remember{mutableStateOf<Long?>(null)};var vehicleId by remember{mutableStateOf(vehicles.firstOrNull()?.id)};var currentKm by remember{mutableStateOf("")};var intervalKm by remember{mutableStateOf("5000")};var oilType by remember{mutableStateOf("")};var note by remember{mutableStateOf("")};var due by remember{mutableStateOf(PersianDate.today().plusMonths(6))};val isVehicle=kind==VEHICLE_ENTRY;val accent=if(isVehicle)Color(0xFF1B8F52) else Color(0xFFD33B45);val canonicalPlate=ir.kharjyar.app.core.sms.IranianPlateMatcher.canonical(plate)
 Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){TextButton(onCancel){Icon(Icons.Filled.ArrowBack,null);Text("بازگشت به فهرست")};Text(if(isVehicle)"ثبت وسیله نقلیه" else "ثبت سرویس و تعویض روغن",style=MaterialTheme.typography.headlineSmall,color=accent);if(isVehicle){OutlinedTextField(title,{title=it},label={Text("نام وسیله نقلیه")},modifier=Modifier.fillMaxWidth());IranianPlateInput(plate,{plate=it});Text(canonicalPlate?.let{"پلاک استاندارد: ${Digits.toPersian(it)}"}?:"چهار بخش پلاک را کامل کنید.",color=if(plate.isNotBlank()&&canonicalPlate==null)MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodySmall);Text("مالک");Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(owner==null,{owner=null},{Text("خودم")});people.forEach{p->FilterChip(owner==p.id,{owner=p.id},{Text(p.name)})}}}else{Text("انتخاب وسیله نقلیه");Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(6.dp)){vehicles.forEach{v->FilterChip(vehicleId==v.id,{vehicleId=v.id},{Text(v.title)})}};OutlinedTextField(currentKm,{currentKm=Digits.normalize(it).filter(Char::isDigit)},label={Text("کیلومتر فعلی")},modifier=Modifier.fillMaxWidth());OutlinedTextField(intervalKm,{intervalKm=Digits.normalize(it).filter(Char::isDigit)},label={Text("فاصله تعویض بعدی (کیلومتر)")},modifier=Modifier.fillMaxWidth());OutlinedTextField(oilType,{oilType=it},label={Text("نوع یا برند روغن")},modifier=Modifier.fillMaxWidth());OutlinedTextField(note,{note=it},label={Text("توضیحات")},modifier=Modifier.fillMaxWidth());Text("موعد زمانی تعویض بعدی");PersianDateField(due,{due=it})};Button({scope.launch{if(isVehicle)dao.insertVehicle(VehicleEntity(ownerId=owner,title=title.trim(),plate=canonicalPlate?:return@launch))else{val selected=vehicles.firstOrNull{it.id==vehicleId}?:return@launch;val nowKm=currentKm.toIntOrNull()?:0;val nextKm=nowKm+(intervalKm.toIntOrNull()?:5000);val at=due.startOfDayMillis()+9*60*60*1000L;val reminderId=vm.repo.db.reminderDao().insert(ReminderEntity(title="تعویض روغن ${selected.title}",category="تعویض روغن خودرو",note="پلاک ${selected.plate} — موعد کیلومتر ${Digits.toPersian(nextKm.toString())}",nextAt=at));LifeReminderWorker.schedule(context,reminderId,at);dao.insertOilService(VehicleOilServiceEntity(vehicleId=selected.id,servicedAt=System.currentTimeMillis(),currentKm=nowKm,nextKm=nextKm,nextDueAt=at,oilType=oilType.trim(),note=note.trim(),reminderId=reminderId))};showSavedMessage(context,"اطلاعات وسیله نقلیه");onDone()}},enabled=if(isVehicle)title.isNotBlank()&&canonicalPlate!=null else vehicleId!=null&&currentKm.isNotBlank(),modifier=Modifier.fillMaxWidth(),border=BorderStroke(1.5.dp,accent)){Text(if(isVehicle)"ثبت وسیله نقلیه" else "ثبت سرویس و فعال‌سازی یادآور")}}
}
